-- R32.42 · IDEA-276/DOL-42 · Institució municipal neutral, sense propietària
-- fins a verificació del domini i acreditació manual per superadmin AAL2.
-- Font del sembrat: src/data/nomenclator/municipis_ine_2026_espanya.v1.json.
-- Els noms ambigus no s'assignen automàticament. No toca ajuntaments existents.
-- v1.2.23 · M3-01 (ordre del Mestre 261123) · resol_reclamacio pot rebutjar (mai aprovar) una reclamació genèrica
-- d'un city_hall feta abans d'esta migració, amb rastre a private.ajuntament_auditoria; cap fila no es tanca sola.
begin;
set local lock_timeout = '5s';
set local statement_timeout = '60s';
alter table public.organizations add column if not exists claimed boolean not null default false;
alter table public.organizations add column if not exists municipi_ine text;
create unique index if not exists organizations_ajuntament_ine_tenant
 on public.organizations(tenant_id) where kind='city_hall' and municipi_ine is not null;
create table if not exists private.ajuntament_municipis_ine (
 ine text primary key check(ine ~ '^[0-9]{5}$'), nom text not null, noms text[] not null,
 font_sha256 text not null check(length(font_sha256)=64)
);
revoke all on private.ajuntament_municipis_ine from public,anon,authenticated;
on conflict(ine) do nothing;
create or replace function private.add_organization_owner()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.created_by is null and new.kind='city_hall' then return new; end if;
    organization_id,
    tenant_id,
    user_id,
    role
  ) values (
    new.id,
    new.tenant_id,
    new.created_by,
    'owner'
  );
  return new;
end;
$$;

-- Només coincidència literal (nom oficial o variant documentada), única en INE.
-- No s'inventa municipi a partir d'un slug, ni per semblança de noms.
with candidats as (
 select t.id,i.ine,i.nom,row_number() over(partition by t.id order by i.ine) n,
 count(*) over(partition by t.id) total
 from public.towns t join private.ajuntament_municipis_ine i on t.name=any(i.noms)
 where t.is_open
)
-- v1.2.23 · R2D-02 (Gauntlet R2) · El nom públic segueix la regla de nomDeLaGent (src/sections/pobles/nomsDelPoble.js):
-- l'article es contrau amb «de» i va en minúscula («del Campello», «de la Torre de les Maçanes», «de l'Alfàs del Pi»),
-- i «de» s'apostrofa davant de vocal o de h més vocal («d'Alcoi», «d'Hondón»), però no davant d'una i o una u
-- semivocals («de Iurreta», «de Huelva»). Les classes porten les majúscules i les minúscules explícites: no depenen
-- de ~* ni de lower() en la col·lació C. Ningú no pot esmenar el nom fins a l'acreditació.
select c.id,'ajuntament-'||c.ine,left('Ajuntament '||case
  when c.nom ~ '^[Ee]ls\s' then 'dels '||regexp_replace(c.nom,'^[Ee]ls\s+','')
  when c.nom ~ '^[Ee]l\s' then 'del '||regexp_replace(c.nom,'^[Ee]l\s+','')
  when c.nom ~ '^[Ll]es\s' then 'de les '||regexp_replace(c.nom,'^[Ll]es\s+','')
  when c.nom ~ '^[Ll]a\s' then 'de la '||regexp_replace(c.nom,'^[Ll]a\s+','')
  when c.nom ~ '^[Ll][''’]' then 'de l'''||regexp_replace(c.nom,'^[Ll][''’]\s*','')
  when c.nom ~ '^[Hh]?[AEIOUÀÁÈÉÍÏÒÓÚÜaeiouàáèéíïòóúü]' and c.nom !~ '^[Hh]?([Ii][aeouàáèéòóúü]|[Uu][aeoàáèéòó])' then 'd'''||c.nom
  else 'de '||c.nom end,120),'city_hall',
 'Fitxa municipal pendent d’acreditació oficial','public',null,false,c.ine
from candidats c where c.total=1 and c.n=1
and not exists(select 1 from public.organizations o where o.tenant_id=c.id and o.kind='city_hall')
on conflict do nothing;

grant select(claimed,municipi_ine) on public.organizations to anon,authenticated;
-- Afegix columnes al final, preservant l'ordre i totes les columnes anteriors.
do $block$
declare cols text;
begin
 select string_agg(format('o.%I',column_name),', ' order by ordinal_position) into cols
 from information_schema.columns where table_schema='public' and table_name='organization_directory'
 and column_name not in ('claimed','municipi_ine');
 if cols is not null then
 execute 'create or replace view public.organization_directory with(security_invoker=true,security_barrier=true) as select '
 ||cols||',o.claimed,o.municipi_ine from public.organizations o where o.visibility=''public''';
 end if;
end $block$;

create table if not exists private.ajuntament_dominis_oficials(
 organization_id uuid not null references public.organizations(id) on delete cascade,
 domini text not null check(domini=lower(domini) and domini ~ '^[a-z0-9]([a-z0-9.-]*[a-z0-9])?\.[a-z]{2,}$' and domini not like '%..%'),
 evidencia text not null check(length(btrim(evidencia)) between 20 and 2000),
 verificat_per uuid references auth.users(id) on delete set null, verificat_at timestamptz not null default now(),
 primary key(organization_id,domini)
);
create table if not exists private.ajuntament_acreditacions(
 claim_id uuid primary key references public.organization_claims(id) on delete cascade,
 correu_verificat text not null, domini text not null,
 evidencia_domini text not null, resolucio_evidencia text, regularitzacio boolean not null default false,
 check(resolucio_evidencia is null or length(btrim(resolucio_evidencia)) between 20 and 2000)
);
create table if not exists private.ajuntament_auditoria(
 id bigint generated always as identity primary key,
 organization_id uuid not null references public.organizations(id) on delete cascade,
 claim_id uuid references public.organization_claims(id) on delete set null,
 actor_id uuid references auth.users(id) on delete set null, accio text not null,
 evidencia text not null, creat_at timestamptz not null default now()
);
revoke all on private.ajuntament_dominis_oficials,private.ajuntament_acreditacions,private.ajuntament_auditoria from public,anon,authenticated;

create or replace function public.registra_domini_ajuntament(p_org uuid,p_domini text,p_evidencia text)
returns void language plpgsql security definer set search_path='' as $$
declare d text:=lower(btrim(p_domini)); e text:=btrim(p_evidencia);
begin
 if not coalesce((select private.es_superadmin()),false) then raise exception 'SDP-AJT-010: cal superadmin AAL2' using errcode='42501'; end if;
 if d is null or d !~ '^[a-z0-9]([a-z0-9.-]*[a-z0-9])?\.[a-z]{2,}$' or d like '%..%' or length(d)>253
 or e is null or length(e) not between 20 and 2000 then raise exception 'SDP-AJT-011: domini o evidència no vàlids' using errcode='22023'; end if;
 perform 1 from public.organizations where id=p_org and kind='city_hall' for update;
 if not found then raise exception 'SDP-AJT-001: no és un ajuntament' using errcode='22023'; end if;
 on conflict(organization_id,domini) do update set evidencia=excluded.evidencia,verificat_per=excluded.verificat_per,verificat_at=excluded.verificat_at;
end $$;

create or replace function public.sollicita_acreditacio_ajuntament(p_org uuid,p_justificacio text)
returns public.organization_claims language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); o public.organizations; c public.organization_claims; email text; d text; e text;
begin
 if u is null then raise exception 'SDP-AJT-000: cal sessió' using errcode='42501'; end if;
 select * into o from public.organizations where id=p_org and kind='city_hall' for update;
 if not found then raise exception 'SDP-AJT-001: no és un ajuntament' using errcode='22023'; end if;
 if o.claimed or exists(select 1 from public.organization_memberships m where m.organization_id=p_org and m.role='owner' and m.user_id<>u) then raise exception 'SDP-AJT-002: ja acreditat o amb altra titular; revisió necessària' using errcode='23505'; end if;
 if p_justificacio is null or length(btrim(p_justificacio)) not between 20 and 1000 then raise exception 'SDP-AJT-003: cal justificació institucional' using errcode='22023'; end if;
 select lower(btrim(a.email)) into email from auth.users a where a.id=u and a.email_confirmed_at is not null and (to_jsonb(a)->>'deleted_at') is null and (a.banned_until is null or a.banned_until<now());
 if email is null or email !~ '^[^@[:space:]]+@[^@[:space:]]+$' then raise exception 'SDP-AJT-004: cal correu verificat' using errcode='42501'; end if;
 d:=split_part(email,'@',2);
 select evidencia into e from private.ajuntament_dominis_oficials where organization_id=p_org and domini=d;
 if e is null then raise exception 'SDP-AJT-005: domini municipal no acreditat' using errcode='42501'; end if;
 return c;
end $$;

create or replace function public.resol_acreditacio_ajuntament(p_claim uuid,p_aprova boolean,p_evidencia text)
returns void language plpgsql security definer set search_path='' as $$
declare c public.organization_claims; o public.organizations; a private.ajuntament_acreditacions; email text;
begin
 if not coalesce((select private.es_superadmin()),false) then raise exception 'SDP-AJT-010: cal superadmin AAL2' using errcode='42501'; end if;
 if p_aprova is null or p_evidencia is null or length(btrim(p_evidencia)) not between 20 and 2000 then raise exception 'SDP-AJT-011: cal resolució i evidència institucional' using errcode='22023'; end if;
 -- Bloqueig sempre organització→reclamació: serialitza aprovacions diferents.
 select * into c from public.organization_claims where id=p_claim;
 select * into o from public.organizations where id=c.organization_id and kind='city_hall' for update;
 select * into c from public.organization_claims where id=p_claim and estat='pendent' for update;
 select * into a from private.ajuntament_acreditacions where claim_id=p_claim;
 if c.id is null or o.id is null or a.claim_id is null then raise exception 'SDP-AJT-012: sol·licitud absent o resolta' using errcode='22023'; end if;
 if c.user_id=auth.uid() then raise exception 'SDP-AJT-013: autorevisió prohibida' using errcode='42501'; end if;
 if p_aprova then
  select lower(btrim(u.email)) into email from auth.users u where u.id=c.user_id and u.email_confirmed_at is not null and (to_jsonb(u)->>'deleted_at') is null and (u.banned_until is null or u.banned_until<now());
  if email is distinct from a.correu_verificat or not exists(select 1 from private.ajuntament_dominis_oficials d where d.organization_id=o.id and d.domini=a.domini) then raise exception 'SDP-AJT-014: acreditació de correu revocada' using errcode='42501'; end if;
  if o.claimed or exists(select 1 from public.organization_memberships m where m.organization_id=o.id and m.role='owner' and m.user_id<>c.user_id) then raise exception 'SDP-AJT-002: ja acreditat o amb altra titular' using errcode='23505'; end if;
  update public.organizations set claimed=true,description=case when description='Fitxa municipal pendent d’acreditació oficial' then '' else description end where id=o.id;
 end if;
 update public.organization_claims set estat=case when p_aprova then 'aprovada' else 'rebutjada' end,resolta_per=auth.uid(),resolta_at=now() where id=c.id;
 update private.ajuntament_acreditacions set resolucio_evidencia=btrim(p_evidencia) where claim_id=c.id;
end $$;
revoke execute on function public.registra_domini_ajuntament(uuid,text,text),public.sollicita_acreditacio_ajuntament(uuid,text),public.resol_acreditacio_ajuntament(uuid,boolean,text) from public,anon;
grant execute on function public.registra_domini_ajuntament(uuid,text,text),public.sollicita_acreditacio_ajuntament(uuid,text),public.resol_acreditacio_ajuntament(uuid,boolean,text) to authenticated;
create or replace function public.sollicita_reclamacio(
  p_organization_id uuid,
  p_justificacio    text default ''
)
returns public.organization_claims
language plpgsql security definer set search_path = ''
as $$
declare v_tenant uuid; v_fila public.organization_claims;
begin
  if (select auth.uid()) is null then
    raise exception 'SDP-CLAIM-000: cal sessió.' using errcode = '42501';
  end if;

  if exists(select 1 from public.organizations where id=p_organization_id and kind='city_hall') then raise exception 'SDP-AJT-020: usa sollutia acreditació institucional' using errcode='42501'; end if;
  select o.tenant_id into v_tenant
    from public.organizations o where o.id = p_organization_id;
  if v_tenant is null then
    raise exception 'SDP-CLAIM-001: l''entitat no existix.' using errcode = '22023';
  end if;

  if not exists (
    select 1 from public.town_memberships tm
    where tm.user_id = (select auth.uid()) and tm.town_id = v_tenant
  ) then
    raise exception 'SDP-CLAIM-002: no eres del poble d''esta entitat.' using errcode = '42501';
  end if;

  if exists (
    select 1 from public.organization_memberships m
    where m.organization_id = p_organization_id and m.role = 'owner'
  ) then
    raise exception 'SDP-CLAIM-003: l''entitat ja té propietària.' using errcode = '23505';
  end if;

  values (p_organization_id, v_tenant, (select auth.uid()),
          left(btrim(coalesce(p_justificacio, '')), 1000))
  returning * into v_fila;

  return v_fila;
end;
$$;
revoke execute on function public.sollicita_reclamacio(uuid, text) from public, anon;
grant execute on function public.sollicita_reclamacio(uuid, text) to authenticated;

create or replace function public.resol_reclamacio(p_claim uuid, p_aprova boolean)
returns void
language plpgsql security definer set search_path = ''
as $$
declare v_claim public.organization_claims; v_ajuntament boolean;
begin
  if not (select private.es_superadmin()) then
    raise exception 'SDP-CLAIM-010: cal rol de superadmin.' using errcode = '42501';
  end if;

  select * into v_claim from public.organization_claims
   where id = p_claim and estat = 'pendent' for update;
  if v_claim.id is null then
    raise exception 'SDP-CLAIM-011: reclamació inexistent o ja resolta.' using errcode = '22023';
  end if;

  -- v1.2.23 · M3-01 (ordre del Mestre 261123) · Un city_hall només s'aprova per la via institucional
  -- (resol_acreditacio_ajuntament). Una reclamació genèrica d'abans d'esta migració sí que es pot rebutjar,
  -- perquè no quede pendent per sempre ni bloquege idx_claims_una_pendent; una sol·licitud institucional
  -- (amb fila a private.ajuntament_acreditacions) no passa mai per ací, ni per a rebutjar-la.
  v_ajuntament := exists(select 1 from public.organizations where id=v_claim.organization_id and kind='city_hall');
  if v_ajuntament and (p_aprova is true or exists(select 1 from private.ajuntament_acreditacions a where a.claim_id=v_claim.id)) then
    raise exception 'SDP-AJT-020: usa resolució institucional' using errcode='42501';
  end if;
  if v_claim.user_id = (select auth.uid()) then
    raise exception 'SDP-CLAIM-012: no pots revisar la teua pròpia reclamació.' using errcode = '42501';
  end if;

  if p_aprova then
    values (v_claim.organization_id, v_claim.tenant_id, v_claim.user_id, 'owner')
    on conflict (organization_id, user_id) do update set role = 'owner';
  end if;

  update public.organization_claims
     set estat = case when p_aprova then 'aprovada' else 'rebutjada' end,
         resolta_per = (select auth.uid()),
         resolta_at  = now()
   where id = p_claim;

  -- v1.2.23 · M3-01 (ordre del Mestre 261123) · El rebuig d'una reclamació genèrica d'un ajuntament queda al rastre.
  if v_ajuntament then
    values(v_claim.organization_id,v_claim.id,(select auth.uid()),'reclamacio_generica_rebutjada',
      'Reclamació genèrica anterior a l’acreditació institucional, rebutjada per superadmin');
  end if;
end;
$$;
revoke execute on function public.resol_reclamacio(uuid, boolean) from public, anon;
grant execute on function public.resol_reclamacio(uuid, boolean) to authenticated;


create or replace function public.pot_signar_com_organitzacio(p_org_id uuid, p_tenant_id uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select p_org_id is null
    or exists (
      select 1
      from public.organization_memberships m
      join public.organizations o on o.id = m.organization_id
      where m.organization_id = p_org_id
        and m.user_id = (select auth.uid())
        and m.role in ('owner', 'admin')
        and (o.kind <> 'city_hall' or (o.claimed and o.tenant_id = p_tenant_id))
    );
$$;

revoke execute on function public.pot_signar_com_organitzacio(uuid, uuid) from public, anon;
grant execute on function public.pot_signar_com_organitzacio(uuid, uuid) to authenticated;

notify pgrst,'reload schema';
commit;
