  insert into public.organization_memberships (
insert into public.organizations(tenant_id,slug,name,kind,description,visibility,created_by,claimed,municipi_ine)
 insert into private.ajuntament_dominis_oficials values(p_org,d,e,auth.uid(),now())
 insert into private.ajuntament_auditoria(organization_id,actor_id,accio,evidencia) values(p_org,auth.uid(),'domini_verificat',d||': '||e);
 insert into public.organization_claims(organization_id,tenant_id,user_id,justificacio) values(p_org,o.tenant_id,u,btrim(p_justificacio)) returning * into c;
 insert into private.ajuntament_acreditacions(claim_id,correu_verificat,domini,evidencia_domini,regularitzacio) values(c.id,email,d,e,exists(select 1 from public.organization_memberships m where m.organization_id=p_org and m.role='owner' and m.user_id=u));
 insert into private.ajuntament_auditoria(organization_id,claim_id,actor_id,accio,evidencia) values(p_org,c.id,u,'sollicitada','Correu institucional verificat; pendent d’aprovació manual');
  insert into public.organization_memberships(organization_id,tenant_id,user_id,role) values(o.id,o.tenant_id,c.user_id,'owner') on conflict(organization_id,user_id) do update set role='owner';
 insert into private.ajuntament_auditoria(organization_id,claim_id,actor_id,accio,evidencia) values(o.id,c.id,auth.uid(),case when p_aprova and a.regularitzacio then 'regularitzada' when p_aprova then 'aprovada' else 'rebutjada' end,btrim(p_evidencia));
  insert into public.organization_claims (organization_id, tenant_id, user_id, justificacio)
    insert into public.organization_memberships (organization_id, tenant_id, user_id, role)
    insert into private.ajuntament_auditoria(organization_id,claim_id,actor_id,accio,evidencia)
